script:
"=== installing Hermes Agent via GitHub ==="
try {
  irm https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.ps1 -OutFile $env:TEMP\hermes-install.ps1
  "Downloaded installer"
  & $env:TEMP\hermes-install.ps1 2>&1 | Select-Object -Last 10
} catch {
  "Install failed: " + $_.Exception.Message
}
